#!/usr/bin/env python3

# The byte sequence from 0xF0-0x140
data = bytes.fromhex('9f09b5a3d78fb301 0b0bd7fdf3c9d7a5 b78dd79919 05d7b7 b50fd7b3018f8f0b 85a3d70ba3ab89d7 01d7db09c393'.replace(' ', ''))

def analyze_pairs():
    # Split into pairs and analyze
    pairs = [(data[i], data[i+1]) for i in range(0, len(data), 2)]

    print("=== Analyzing byte pairs ===")
    first_bytes = []
    for first, second in pairs:
        first_bytes.append(first)
        print(f"Pair: {hex(first)} {hex(second)}")
    return first_bytes

def try_decode_ascii(bytes_list):
    print("\n=== ASCII Decoding ===")
    try:
        ascii_text = ''.join(chr(b) for b in bytes_list if 32 <= b <= 126)
        print(f"ASCII text (printable): {ascii_text}")
    except:
        print("Failed ASCII decode")

def try_xor_decoding(bytes_list):
    print("\n=== XOR Analysis ===")
    common_xor_values = [0x1f, 0x20, 0x7f, 0xff]

    for xor_val in common_xor_values:
        xored = [b ^ xor_val for b in bytes_list]
        try:
            ascii_text = ''.join(chr(b) for b in xored if 32 <= b <= 126)
            if ascii_text:
                print(f"XOR with {hex(xor_val)}: {ascii_text}")
        except:
            continue

def analyze_d71f_sections():
    print("\n=== d71f Pattern Analysis ===")
    hex_str = data.hex()
    sections = hex_str.split('d7')
    print("Sections separated by d7:")
    for section in sections:
        if section:
            print(f"Section: {section}")

def main():
    first_bytes = analyze_pairs()
    try_decode_ascii(first_bytes)
    try_xor_decoding(first_bytes)
    analyze_d71f_sections()

if __name__ == '__main__':
    main()
